function auth_user()
{
    if (!empty($GLOBALS['LEGACY_USER'])) {
        return $GLOBALS['LEGACY_USER'];
    }
    if (isset($_SESSION['admin_id'])) {
        return db_one("SELECT * FROM admin_users WHERE id = " . (int) $_SESSION['admin_id']);
    }

    return null;
}

function auth_login_name()
{
    $u = auth_user();

    return $u ? $u['login'] : 'admin';
}

/**
 * Ma uzivatel roli? Admin muze vsechno.
 */
function auth_has_role($role)
{
    $u = auth_user();
    if ($u === null) {
        // FIXME: bez session (za Symfony firewallem) bereme jako admina
        return true;
    }
    if ($u['role'] == 'admin') {
        return true;
    }

    return $u['role'] == $role;
}

/**
 * Pusti dal jen prihlaseneho uzivatele s roli $role (admin muze vsechno),
 * jinak vyhodi AccessDenied (-> 403). Bez $role staci byt prihlaseny.
 *
 * Firewall pred /admin pousti jen ROLE_STAFF, roli stare administrace
 * (admin, obchod, sklad, ucetni) prebira LegacyFrontController z roli
 * Symfony uzivatele (ROLE_ADMIN, ROLE_OBCHOD, ...).
 */
function auth_require($role = null)
{
    if (auth_user() === null) {
        throw new AccessDenied('Nepřihlášený uživatel');
    }
    if ($role !== null && !auth_has_role($role)) {
        throw new AccessDenied('Nemáte oprávnění');
    }

    return true;
}
<?php
/**
 * Ochrana formularu proti CSRF (podvrzenemu pozadavku z ciziho webu).
 *
 * Kazda akce, ktera meni data:
 *
 *     // formular: hned za <form method="post">
 *     echo csrf_field();
 *
 *     // akce: hned po auth_require()
 *     if (is_post()) {
 *         csrf_check();
 *         ...
 *     }
 *
 * Token je jeden na session. Ulozi ho do session LegacyFrontController
 * a preda v $GLOBALS['LEGACY_CSRF_TOKEN']; mimo nej (cron, testy) se vygeneruje.
 */

use App\Legacy\lib\AccessDenied;

function csrf_token()
{
    if (empty($GLOBALS['LEGACY_CSRF_TOKEN']) || !is_string($GLOBALS['LEGACY_CSRF_TOKEN'])) {
        $GLOBALS['LEGACY_CSRF_TOKEN'] = bin2hex(random_bytes(32));
    }

    return $GLOBALS['LEGACY_CSRF_TOKEN'];
}

/**
 * Skryte pole s tokenem do kazdeho formulare s method="post".
 */
function csrf_field()
{
    return '<input type="hidden" name="_csrf" value="' . h(csrf_token()) . '">';
}

/**
 * Overi token z POSTu. Bez platneho tokenu vyhodi AccessDenied (-> 403), nic se neulozi.
 */
function csrf_check()
{
    $sent = isset($_POST['_csrf']) ? $_POST['_csrf'] : '';
    if (!is_string($sent) || $sent === '' || !hash_equals(csrf_token(), $sent)) {
        throw new AccessDenied('Neplatný bezpečnostní token formuláře. Načtěte stránku znovu a akci opakujte.');
    }

    return true;
}
function h($s)
{
    return htmlspecialchars((string) $s, ENT_QUOTES, 'UTF-8');
}

/**
 * Parametr z GET, nikdy null.
 */
function get_param($name, $default = '')
{
    if (!isset($_GET[$name])) {
        return $default;
    }
    if (is_array($_GET[$name])) {
        return $_GET[$name];
    }

    return trim((string) $_GET[$name]);
}

function post_param($name, $default = '')
{
    if (!isset($_POST[$name])) {
        return $default;
    }
    if (is_array($_POST[$name])) {
        return $_POST[$name];
    }

    return trim((string) $_POST[$name]);
}

function is_post()
{
    return isset($_SERVER['REQUEST_METHOD']) && strtoupper($_SERVER['REQUEST_METHOD']) == 'POST' || !empty($_POST);
}

/**
 * Cena v halerich -> "1 234,50 Kč"
 */
function format_price($cents, $currency = 'CZK')
{
    $amount = ((int) $cents) / 100;
    $s = number_format($amount, 2, ',', ' ');
    switch ($currency) {
        case 'CZK':
            return $s . ' Kč';
        case 'EUR':
            return $s . ' €';
        case 'USD':
            return '$' . $s;
        default:
            return $s . ' ' . $currency;
    }
}

/**
 * Datum z DB -> 5. 10. 2026
 */
function format_date($dbDate, $withTime = false)
{
 */
function ids_to_sql($ids)
{
    $out = array();
    foreach ((array) $ids as $id) {
        $out[] = "'" . db_escape_old($id) . "'";
    }

    return implode(',', $out);
}

/**
 * Prikaz pro novy e-shop (src/Ordering). Vraci vysledek handleru.
 * Most pripravi $GLOBALS['LEGACY_COMMAND'] (viz Http/LegacyFrontController).
 */
function legacy_command($command)
{
    if (!isset($GLOBALS['LEGACY_COMMAND']) || !is_callable($GLOBALS['LEGACY_COMMAND'])) {
        throw new \RuntimeException('Příkazy nového e-shopu jdou volat jen přes /admin/legacy');
    }

    return call_user_func($GLOBALS['LEGACY_COMMAND'], $command);
}

